//! Design tokens for the server's own HTML: emails and fallback pages.
//!
//! Generated by scripts/generate-design-tokens.mjs from packages/ui/tokens/tokens.json. Do not edit.
//! Colors are sRGB because email clients do not understand OKLCH.

/// The colors of one theme.
#[derive(Debug, Clone, Copy)]
pub struct Theme {
    /// App and page background
    pub canvas: &'static str,
    /// Surface 1: cards, panels, list columns
    pub surface: &'static str,
    /// Surface 2: hover rows, nested cards, dialog footers
    pub surface_raised: &'static str,
    /// Surface 3: menus, popovers, dialogs, sheets
    pub surface_overlay: &'static str,
    /// Text field and search background
    pub field: &'static str,
    /// Wells: segmented-control tracks, code blocks, input groups
    pub surface_sunken: &'static str,
    /// Tooltips and inverse chips
    pub surface_inverse: &'static str,
    /// Dividers and glass edges (translucent)
    pub hairline: &'static str,
    /// Card and control borders
    pub border: &'static str,
    /// Input borders, emphasized outlines
    pub border_strong: &'static str,
    /// Primary text
    pub text: &'static str,
    /// Secondary text (alias: text-secondary)
    pub text_muted: &'static str,
    /// Muted text: captions, placeholders, meta
    pub text_subtle: &'static str,
    /// Text on surface-inverse
    pub text_inverse: &'static str,
    /// Electric blue fill: primary buttons, selected rows, switches
    pub accent: &'static str,
    /// Hover on accent fills
    pub accent_hover: &'static str,
    /// Pressed accent fills
    pub accent_pressed: &'static str,
    /// Tinted backgrounds: badges, selected chips, icon tiles
    pub accent_soft: &'static str,
    /// Text and icons on accent
    pub accent_contrast: &'static str,
    /// Links and accent text on canvas and surfaces (Tailwind `text-accent`)
    pub accent_text: &'static str,
    /// Focus ring
    pub focus: &'static str,
    /// Success icons, bars, fills
    pub success: &'static str,
    /// Success text
    pub success_text: &'static str,
    /// Success backgrounds
    pub success_soft: &'static str,
    /// Text on success fills
    pub success_contrast: &'static str,
    /// Warning icons, bars, the orange update banner
    pub warning: &'static str,
    /// Warning text
    pub warning_text: &'static str,
    /// Warning backgrounds
    pub warning_soft: &'static str,
    /// Text on warning fills (ink, not white, for AA)
    pub warning_contrast: &'static str,
    /// Danger icons and fills (destructive buttons)
    pub danger: &'static str,
    /// Danger text
    pub danger_text: &'static str,
    /// Danger backgrounds
    pub danger_soft: &'static str,
    /// Text on danger fills
    pub danger_contrast: &'static str,
    /// Info icons
    pub info: &'static str,
    /// Info text
    pub info_text: &'static str,
    /// Info backgrounds
    pub info_soft: &'static str,
    /// Behind dialogs and sheets
    pub scrim: &'static str,
    /// Desktop window and floating bars (with backdrop blur)
    pub glass: &'static str,
    /// Edge of glass surfaces
    pub glass_border: &'static str,
    /// Tile behind favicons (light in both themes so dark marks stay visible)
    pub icon_tile: &'static str,
    /// Inner ring of favicon tiles
    pub icon_tile_ring: &'static str,
}

